// ============================================================================
// 2. HELPER FUNCTIONS & SMALL COMPONENTS
// ============================================================================

function createDeck() {
  const deck: any[] = [];
  let uid = 1;
  Object.values(CARD_TYPES).forEach(card => {
    for (let i = 0; i < card.count; i++) {
      deck.push({ uid: `card_${uid++}`, ...card });
    }
  });
  return shuffle(deck);
}

function shuffle(array: any[]) {
  const arr = [...array];
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

const nowStr = () => new Date().toLocaleTimeString('th-TH');

function CardArt({ id, className = '' }: { id: string; className?: string }) {
  return (
    <img
      src={(CARD_IMAGES as any)[id]}
      alt={(CARD_TYPES as any)[id].name}
      draggable={false}
      className={`select-none ${className}`}
    />
  );
}

function Overlay({ children, z = 'z-50', onClose }: { children?: any; z?: string; onClose?: () => void }) {
  return (
    <div
      className={`fixed inset-0 ${z} bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-4`}
      onClick={onClose}
    >
      <div onClick={e => e.stopPropagation()} className="w-full flex justify-center">
        {children}
      </div>
    </div>
  );
}

function TipList({ tips }: { tips: string[] }) {
  return (
    <ul className="text-left text-sm text-slate-600 space-y-1.5 leading-snug">
      {tips.map((t, i) => (
        <li key={i} className="flex gap-2">
          <span className="text-sky-400 font-black">•</span>
          <span>{t}</span>
        </li>
      ))}
    </ul>
  );
}

// ============================================================================
// 3. MAIN APP COMPONENT
// ============================================================================

export default function App() {
  const [numPlayers, setNumPlayers] = useState<number | null>(null);
  const [deck, setDeck] = useState<any[]>([]);
  const [discardPile, setDiscardPile] = useState<any[]>([]);
  const [players, setPlayers] = useState<any[]>([]);
  const [turnPlayerId, setTurnPlayerId] = useState(1);
  const [viewPlayerId, setViewPlayerId] = useState(1);
  const [isHandVisible, setIsHandVisible] = useState(false);
  // action: null (ยังไม่เลือก) | 'draw' | 'roll'
  const [turn, setTurn] = useState<any>({ number: 1, action: null, draws: 0, canRoll: true });
  const [finallyOverActive, setFinallyOverActive] = useState(false);
  const [endScene, setEndScene] = useState<any>(null); // { turnsLeft }
  const [gameOver, setGameOver] = useState<any>(null); // { title, detail }
  const [lastPlayed, setLastPlayed] = useState<any>(null);
  const [reveal, setReveal] = useState<any>(null); // { card, playerId, playerName, mode }
  const [preview, setPreview] = useState<any>(null);
  const [dice, setDice] = useState<any>(null); // { value, rolling }
  const [showRules, setShowRules] = useState(false);
  const [showWinPicker, setShowWinPicker] = useState(false);
  const [confirmRestart, setConfirmRestart] = useState(false);
  const [gameLogs, setGameLogs] = useState<any[]>([]);
  const [toast, setToast] = useState<string | null>(null);

  const logBoxRef = useRef<HTMLDivElement | null>(null);
  const toastTimer = useRef<any>(null);
  const diceTimer = useRef<any>(null);
  const finallyOverRef = useRef(false);

  useEffect(() => { finallyOverRef.current = finallyOverActive; }, [finallyOverActive]);

  // Auto-scroll logs (เลื่อนเฉพาะกล่องบันทึก ไม่ดึงทั้งหน้า)
  useEffect(() => {
    if (logBoxRef.current) {
      logBoxRef.current.scrollTop = logBoxRef.current.scrollHeight;
    }
  }, [gameLogs]);

  useEffect(() => () => {
    clearTimeout(toastTimer.current);
    clearInterval(diceTimer.current);
  }, []);

  const showToast = (msg: string) => {
    setToast(msg);
    clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setToast(null), 2800);
  };

  const addLog = (text: string) => {
    setGameLogs(prev => [...prev, { id: Date.now() + Math.random(), text, time: nowStr() }]);
  };

  // --------------------------------------------------------------------------
  // Game setup
  // --------------------------------------------------------------------------
  const startGame = (n: number) => {
    clearInterval(diceTimer.current);
    setNumPlayers(n);
    setDeck(createDeck());
    setDiscardPile([]);
    setPlayers(PLAYERS.slice(0, n).map(p => ({ ...p, hand: [] })));
    setTurnPlayerId(1);
    setViewPlayerId(1);
    setIsHandVisible(false);
    setTurn({ number: 1, action: null, draws: 0, canRoll: true });
    setFinallyOverActive(false);
    setEndScene(null);
    setGameOver(null);
    setLastPlayed(null);
    setReveal(null);
    setPreview(null);
    setDice(null);
    setShowRules(false);
    setShowWinPicker(false);
    setConfirmRestart(false);
    setGameLogs([{ id: Date.now(), text: `เริ่มเกม ${n} คน! สับไพ่ 72 ใบเรียบร้อย`, time: nowStr() }]);
  };

  const backToSetup = () => {
    clearInterval(diceTimer.current);
    setNumPlayers(null);
    setGameOver(null);
    setShowRules(false);
    setConfirmRestart(false);
  };

  // --------------------------------------------------------------------------
  // Derived state
  // --------------------------------------------------------------------------
  const viewPlayer = players.find(p => p.id === viewPlayerId);
  const turnPlayer = players.find(p => p.id === turnPlayerId);
  const isMyTurn = viewPlayerId === turnPlayerId;

  // --------------------------------------------------------------------------
  // Actions
  // --------------------------------------------------------------------------
  const handleSwitchPlayer = (id: number) => {
    setViewPlayerId(id);
    setIsHandVisible(false);
  };

  const endGame = (title: string, detail: string) => {
    clearInterval(diceTimer.current);
    setGameOver({ title, detail });
    addLog(`🏁 เกมจบ: ${title}`);
  };

  // Draw Card Logic
  const handleDrawCard = () => {
    if (gameOver || !viewPlayer) return;
    if (!isMyTurn) {
      showToast('ยังไม่ถึงเทิร์นของผู้เล่นนี้ — จั่วไพ่ได้เฉพาะเทิร์นของตัวเอง');
      return;
    }
    if (turn.action === 'roll') {
      showToast('เทิร์นนี้เลือกทอยเต๋าไปแล้ว จึงจั่วไพ่ไม่ได้');
      return;
    }
    if (turn.draws >= MAX_DRAWS_PER_TURN) {
      showToast(`จั่วครบ ${MAX_DRAWS_PER_TURN} ใบแล้วในเทิร์นนี้ กด “จบเทิร์น” ได้เลย`);
      return;
    }
    if (viewPlayer.hand.length >= MAX_HAND) {
      showToast(`ไพ่เต็มมือ ${MAX_HAND} ใบแล้ว ใช้หรือทิ้งไพ่ก่อนจึงจะจั่วเพิ่มได้!`);
      return;
    }

    let currentDeck = [...deck];
    let currentDiscard = [...discardPile];

    if (currentDeck.length === 0) {
      if (currentDiscard.length === 0) {
        showToast('ไม่มีไพ่เหลือในกองและกองทิ้ง!');
        return;
      }
      currentDeck = shuffle(currentDiscard);
      currentDiscard = [];
      addLog('🔄 สับกองทิ้งกลับมาเป็นกองจั่วใหม่');
    }

    const drawnCard = currentDeck.pop();
    const mustPlayNow = drawnCard.id === 'finallyOver';

    setDeck(currentDeck);
    setDiscardPile(mustPlayNow ? [...currentDiscard, drawnCard] : currentDiscard);
    setTurn(t => ({ ...t, action: 'draw', draws: t.draws + 1 }));

    if (mustPlayNow) {
      // กติกา: "จบสักที" ต้องเปิดและเล่นทันทีที่จั่วได้ ไม่เก็บไว้บนมือ
      setFinallyOverActive(true);
      setLastPlayed({ card: drawnCard, playerName: viewPlayer.name });
      addLog(`🔥 ${viewPlayer.name} จั่วได้ "จบสักที"! เปิดไพ่ทันที — ใครทอยได้ 6 หลังจากนี้ เกมจบทันที`);
      setReveal({ card: drawnCard, playerId: viewPlayer.id, playerName: viewPlayer.name, mode: 'drawn' });
    } else {
      setPlayers(prev => prev.map(p =>
        p.id === viewPlayer.id ? { ...p, hand: [...p.hand, drawnCard] } : p
      ));
      addLog(`🎴 ${viewPlayer.name} จั่วไพ่ 1 ใบ`);
    }
  };

  // Play Card Logic
  const handlePlayCard = (card: any) => {
    if (gameOver || !viewPlayer) return;

    if (card.id === 'endScene') {
      if (!isMyTurn || turn.action !== null) {
        showToast('“ปิดฉาก” ใช้ได้เฉพาะต้นเทิร์นของตัวเอง ก่อนทอยเต๋าหรือจั่วไพ่');
        return;
      }
      if (endScene) {
        showToast('กำลังนับถอยหลัง “ปิดฉาก” อยู่แล้ว');
        return;
      }
    }

    setPlayers(prev => prev.map(p =>
      p.id === viewPlayer.id ? { ...p, hand: p.hand.filter(c => c.uid !== card.uid) } : p
    ));
    setDiscardPile(prev => [...prev, card]);
    setLastPlayed({ card, playerName: viewPlayer.name });
    addLog(`✨ ${viewPlayer.name} ใช้ไพ่ "${card.name}"`);

    if (card.id === 'endScene') {
      setEndScene({ turnsLeft: END_SCENE_TURNS });
      addLog(`🪼 "ปิดฉาก" เริ่มนับ ${END_SCENE_TURNS} เทิร์น (เทิร์นนี้คือเทิร์นที่ 1)`);
    }

    setReveal({
      card,
      playerId: viewPlayer.id,
      playerName: viewPlayer.name,
      mode: card.id === 'steal' ? 'steal' : 'play'
    });
  };

  // Discard Card (Silent drop)
  const handleDiscardCard = (card: any) => {
    if (gameOver || !viewPlayer) return;
    setPlayers(prev => prev.map(p =>
      p.id === viewPlayer.id ? { ...p, hand: p.hand.filter(c => c.uid !== card.uid) } : p
    ));
    setDiscardPile(prev => [...prev, card]);
    addLog(`🗑️ ${viewPlayer.name} ทิ้งไพ่ 1 ใบ`);
  };

  // Execute Steal
  const executeSteal = (victimId: number) => {
    const thief = players.find(p => p.id === reveal.playerId);
    const victim = players.find(p => p.id === victimId);

    if (victim.hand.length === 0) {
      addLog(`🥷 ${thief.name} พยายามขโมยจาก ${victim.name} แต่ไม่มีไพ่ให้ขโมย — ไม่เกิดผล`);
      showToast(`${victim.name} ไม่มีไพ่บนมือให้ขโมย!`);
      setReveal(null);
      return;
    }

    const randomIndex = Math.floor(Math.random() * victim.hand.length);
    const stolenCard = victim.hand[randomIndex];

    setPlayers(prev => prev.map(p => {
      if (p.id === victim.id) {
        return { ...p, hand: p.hand.filter((_, idx) => idx !== randomIndex) };
      }
      if (p.id === thief.id) {
        // ขโมยได้แม้เคยเต็มมือ 10 ใบ เพราะไพ่ Steal ถูกทิ้งก่อนแล้ว
        return { ...p, hand: [...p.hand, stolenCard] };
      }
      return p;
    }));

    addLog(`🥷 ${thief.name} ขโมยไพ่จาก ${victim.name} สำเร็จ!`);
    setReveal(null);
    showToast(`คุณขโมยไพ่ "${stolenCard.name}" มาได้สำเร็จ!`);
  };

  const cancelSteal = () => {
    addLog(`✋ การขโมยของ ${reveal.playerName} ถูก "หยุดเดี๋ยวนี้" ยกเลิก`);
    setReveal(null);
  };

  // End Turn
  const handleEndTurn = () => {
    if (gameOver || !turnPlayer) return;
    addLog(`⏭️ ${turnPlayer.name} จบเทิร์น`);

    if (endScene) {
      const left = endScene.turnsLeft - 1;
      if (left <= 0) {
        setEndScene({ turnsLeft: 0 });
        endGame('ปิดฉาก! ครบ 4 เทิร์นแล้ว', 'เกมจบทันที ไปนับเกาะและคะแนนบนกระดานเพื่อตัดสินผู้ชนะ');
        return;
      }
      setEndScene({ turnsLeft: left });
    }

    const idx = players.findIndex(p => p.id === turnPlayerId);
    const next = players[(idx + 1) % players.length];
    setTurnPlayerId(next.id);
    setViewPlayerId(next.id);
    setIsHandVisible(false);
    setDice(null);
    setTurn(t => ({ number: t.number + 1, action: null, draws: 0, canRoll: true }));
  };

  // Dice
  const handleRollDice = () => {
    if (gameOver || !turnPlayer) return;
    if (!isMyTurn) {
      showToast('ทอยเต๋าได้เฉพาะผู้เล่นที่ถึงเทิร์น');
      return;
    }
    if (turn.action === 'draw') {
      showToast('เทิร์นนี้เลือกจั่วไพ่ไปแล้ว จึงทอยเต๋าไม่ได้');
      return;
    }
    if (!turn.canRoll) {
      showToast('ทอยได้อีกครั้งเมื่อทอยได้ 6 เท่านั้น — กด “จบเทิร์น” ได้เลย');
      return;
    }

    const player = turnPlayer;
    const finalValue = Math.floor(Math.random() * 6) + 1;
    let ticks = 0;
    setTurn(t => ({ ...t, action: 'roll', canRoll: false }));
    setDice({ value: 1, rolling: true });
    clearInterval(diceTimer.current);
    diceTimer.current = setInterval(() => {
      ticks += 1;
      if (ticks >= 8) {
        clearInterval(diceTimer.current);
        setDice({ value: finalValue, rolling: false });
        addLog(`🎲 ${player.name} ทอยได้ ${finalValue}`);
        if (finalValue === 6) {
          if (finallyOverRef.current) {
            endGame(`${player.name} ทอยได้ 6!`, 'ไพ่ “จบสักที” ทำงานอยู่ — เกมจบทันที ไปนับเกาะและคะแนนบนกระดาน');
          } else {
            setTurn(t => ({ ...t, canRoll: true }));
          }
        }
      } else {
        setDice({ value: Math.floor(Math.random() * 6) + 1, rolling: true });
      }
    }, 80);
  };

  // ประกาศ 6 จากเต๋าจริง ตอนที่ "จบสักที" ทำงานอยู่
  const declareSix = () => {
    endGame(`${turnPlayer.name} ทอยได้ 6!`, 'ไพ่ “จบสักที” ทำงานอยู่ — เกมจบทันที ไปนับเกาะและคะแนนบนกระดาน');
  };

  const declareIslandWin = (player: any) => {
    setShowWinPicker(false);
    endGame(`${player.name} ครอบครอง 4 เกาะ!`, 'ชนะทันที ไม่ว่าไพ่จบเกมจะทำงานอยู่หรือไม่ ไม่ต้องรอจบเทิร์น');
  };

  // --------------------------------------------------------------------------
  // SETUP SCREEN
  // --------------------------------------------------------------------------
  if (numPlayers === null) {
    return (
      <div className="min-h-screen bg-gradient-to-b from-sky-300 via-cyan-200 to-blue-300 flex flex-col items-center justify-center p-6 text-center">
        <style>{ANIM_CSS}</style>
        <div className="text-7xl mb-3">🏝️</div>
        <h1 className="text-4xl font-black text-sky-900 tracking-tight">Island Conquest</h1>
        <p className="text-sky-800 font-bold mb-8">ศึกชิงเกาะ • ตัวจัดการไพ่</p>

        <div className="flex items-end justify-center gap-2 mb-8">
          {['kickOut', 'shield', 'stop', 'reflect'].map((id, i) => (
            <CardArt
              key={id}
              id={id}
              className="w-20 sm:w-24 drop-shadow-xl"
            />
          ))}
        </div>

        <div className="text-sm font-black text-sky-900 mb-3">เลือกจำนวนผู้เล่น</div>
        <div className="flex gap-3">
          {[2, 3, 4].map(n => (
            <button
              key={n}
              onClick={() => startGame(n)}
              className="w-24 py-4 rounded-2xl bg-white text-sky-700 font-black text-xl shadow-lg hover:scale-105 active:scale-95 transition-transform"
            >
              {n} คน
            </button>
          ))}
        </div>
      </div>
    );
  }

  if (!viewPlayer || !turnPlayer) return null;

  const sortedHand = [...viewPlayer.hand].sort(
    (a, b) => CARD_ORDER.indexOf(a.id) - CARD_ORDER.indexOf(b.id)
  );
  const canDraw = isMyTurn && turn.action !== 'roll' && turn.draws < MAX_DRAWS_PER_TURN && viewPlayer.hand.length < MAX_HAND;
  const canRoll = isMyTurn && turn.action !== 'draw' && turn.canRoll && !(dice && dice.rolling);

  // --------------------------------------------------------------------------
  // MAIN SCREEN
  // --------------------------------------------------------------------------
  return (
    <div className="min-h-screen bg-gradient-to-b from-sky-100 via-cyan-50 to-blue-100 flex flex-col font-sans text-slate-800">
      <style>{ANIM_CSS}</style>

      {/* HEADER & DECK STATS */}
      <header className="bg-gradient-to-r from-sky-900 to-blue-900 text-white p-3 sm:p-4 shadow-md flex justify-between items-center gap-2 z-10 sticky top-0">
        <div className="flex items-center gap-2 min-w-0">
          <Layers className="w-6 h-6 text-sky-300 shrink-0" />
          <h1 className="font-black text-lg sm:text-xl tracking-tight truncate">
            Island Conquest<span className="text-sky-300 text-sm ml-2 hidden sm:inline">Card Manager</span>
          </h1>
        </div>
        <div className="flex items-center gap-2">
          <div className="flex gap-3 text-xs sm:text-sm font-bold bg-sky-950/60 px-3 py-2 rounded-full border border-sky-700">
            <div><span className="text-sky-300">กองจั่ว:</span> {deck.length}</div>
            <div className="w-px bg-sky-700"></div>
            <div><span className="text-rose-300">ทิ้ง:</span> {discardPile.length}</div>
          </div>
          <button
            onClick={() => setShowWinPicker(true)}
            className="p-2 rounded-full bg-amber-400 text-amber-900 hover:bg-amber-300"
            title="ประกาศ: ครอบครอง 4 เกาะ"
          >
            <Trophy className="w-5 h-5" />
          </button>
          <button
            onClick={() => setShowRules(true)}
            className="p-2 rounded-full bg-sky-700 hover:bg-sky-600"
            title="สรุปไพ่และกติกา"
          >
            <BookOpen className="w-5 h-5" />
          </button>
        </div>
      </header>

      {/* STATUS BOARD */}
      <section className="bg-white/70 px-4 py-4 shadow-sm border-b border-sky-100">
        <div className="max-w-4xl mx-auto space-y-3">

          {finallyOverActive && (
            <div className="rounded-2xl bg-gradient-to-r from-fuchsia-500 to-rose-500 text-white p-3 flex flex-wrap items-center gap-3 shadow-md">
              <CardArt id="finallyOver" className="w-10 drop-shadow" />
              <div className="flex-1 min-w-[180px]">
                <div className="font-black">🔥 “จบสักที” กำลังทำงาน!</div>
                <div className="text-xs opacity-90">ใครทอยเต๋าได้ 6 เกมจบทันที (หยุดเดี๋ยวนี้ ยกเลิกไม่ได้)</div>
              </div>
              <button
                onClick={declareSix}
                className="px-3 py-2 rounded-xl bg-white text-rose-600 text-xs font-black hover:bg-rose-50"
              >
                ทอยเต๋าจริงได้ 6 แล้ว
              </button>
            </div>
          )}

          {endScene && (
            <div className="rounded-2xl bg-gradient-to-r from-purple-500 to-indigo-500 text-white p-3 flex items-center gap-3 shadow-md">
              <CardArt id="endScene" className="w-10 drop-shadow" />
              <div className="flex-1">
                <div className="font-black">🪼 “ปิดฉาก” กำลังนับเทิร์น</div>
                <div className="text-xs opacity-90">
                  ตอนนี้เทิร์นที่ {END_SCENE_TURNS + 1 - endScene.turnsLeft}/{END_SCENE_TURNS} — เกมจบเมื่อจบเทิร์นที่ {END_SCENE_TURNS}
                </div>
              </div>
            </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">

            {/* Turn + Dice + Last Played */}
            <div className="bg-white rounded-2xl p-4 border border-sky-100 shadow-sm space-y-3">
              <div className="flex items-center justify-between gap-3">
                <div>
                  <div className="text-xs font-bold text-slate-400 uppercase">เทิร์นที่ {turn.number}</div>
                  <div className={`font-black text-lg ${turnPlayer.text}`}>ถึงตา {turnPlayer.name}</div>
                  <div className="text-[11px] text-slate-500 font-bold mt-0.5">
                    {turn.action === 'draw' && `จั่วไพ่แล้ว ${turn.draws}/${MAX_DRAWS_PER_TURN} ใบ`}
                    {turn.action === 'roll' && 'เลือกทอยเต๋าในเทิร์นนี้'}
                    {turn.action === null && 'เลือก 1 อย่าง: ทอยเต๋า หรือ จั่วไพ่ 1–2 ใบ'}
                  </div>
                </div>
                {dice && (
                  <div className="text-center">
                    <div className={`text-5xl leading-none ${dice.rolling ? 'animate-shake' : 'animate-pop'}`}>
                      {DICE_FACES[dice.value - 1]}
                    </div>
                    {!dice.rolling && dice.value === 6 && (
                      <div className="text-[10px] font-black text-amber-600 mt-1">ได้ 6! ออกจากฐาน/เดิน 12 ช่อง แล้วทอยซ้ำ</div>
                    )}
                  </div>
                )}
              </div>

              <div className="border-t border-slate-100 pt-3">
                <div className="text-xs font-bold text-slate-400 uppercase mb-2">ไพ่ที่ถูกใช้ล่าสุด</div>
                {lastPlayed ? (
                  <div className="flex items-center gap-3">
                    <CardArt id={lastPlayed.card.id} className="w-14 drop-shadow-md" />
                    <div>
                      <div className="text-sm font-black text-slate-700">{lastPlayed.card.name}</div>
                      <div className="text-xs font-bold text-slate-500">โดย {lastPlayed.playerName}</div>
                      <div className="text-xs text-slate-400">{lastPlayed.card.desc}</div>
                    </div>
                  </div>
                ) : (
                  <div className="text-sm text-slate-400 italic">ยังไม่มีการใช้ไพ่</div>
                )}
              </div>
            </div>

            {/* Game Log */}
            <div className="bg-sky-950 rounded-2xl p-3 border border-sky-900 h-48 md:h-auto min-h-[12rem] flex flex-col">
              <div className="flex items-center gap-2 text-sky-300 text-xs font-bold uppercase mb-2 border-b border-sky-800 pb-2">
                <History className="w-4 h-4" /> บันทึกเหตุการณ์
              </div>
              <div ref={logBoxRef} className="overflow-y-auto flex-1 text-sm space-y-1 pr-2">
                {gameLogs.map(log => (
                  <div key={log.id} className="text-sky-100 border-l-2 border-sky-700 pl-2">
                    <span className="text-sky-400 text-[10px] mr-2">[{log.time}]</span>
                    {log.text}
                  </div>
                ))}
              </div>
            </div>

          </div>
        </div>
      </section>

      {/* PLAYER TABS */}
      <section className="bg-white border-b border-sky-100 overflow-x-auto">
        <div className="max-w-4xl mx-auto flex">
          {players.map(p => {
            const isView = viewPlayerId === p.id;
            const isTurn = turnPlayerId === p.id;
            return (
              <button
                key={p.id}
                onClick={() => handleSwitchPlayer(p.id)}
                className={`flex-1 min-w-[90px] py-3 px-2 flex flex-col items-center justify-center border-b-4 transition-all ${
                  isView ? `${p.border} bg-slate-50` : 'border-transparent hover:bg-slate-50 text-slate-500'
                }`}
              >
                <span className={`text-xs sm:text-sm font-black ${isView ? p.text : ''}`}>ผู้เล่น {p.id}</span>
                <span className="text-[10px] font-bold mt-1 bg-slate-200 text-slate-600 px-2 py-0.5 rounded-full">
                  ไพ่ {p.hand.length}/{MAX_HAND}
                </span>
                {isTurn && (
                  <span className={`text-[9px] font-black text-white px-2 py-0.5 rounded-full mt-1 ${p.color}`}>▶ เทิร์นนี้</span>
                )}
              </button>
            );
          })}
        </div>
      </section>

      {/* ACTIVE PLAYER HAND AREA */}
      <main className={`flex-1 relative transition-colors duration-500 ${viewPlayer.lightBg}`}>

        {/* PRIVACY SHIELD OVERLAY */}
        {!isHandVisible && (
          <div className="absolute inset-0 z-20 bg-slate-900/90 backdrop-blur-md flex flex-col items-center justify-center p-6 text-center">
            <User className={`w-20 h-20 mb-4 p-4 rounded-full bg-white shadow-xl ${viewPlayer.text}`} />
            <h2 className="text-3xl font-black mb-2 text-white">{viewPlayer.name}</h2>
            <p className="text-slate-300 mb-8 text-sm">
              {isMyTurn ? 'ถึงเทิร์นของคุณแล้ว! ' : ''}ส่งเครื่องให้ผู้เล่นนี้และกดปุ่มด้านล่างเพื่อดูไพ่
            </p>
            <button
              onClick={() => setIsHandVisible(true)}
              className={`px-8 py-4 rounded-2xl text-white font-black text-lg shadow-lg flex items-center gap-3 transition-transform active:scale-95 ${viewPlayer.color}`}
            >
              <Eye className="w-6 h-6" /> ดูไพ่บนมือ
            </button>
          </div>
        )}

        <div className="max-w-4xl mx-auto p-4 pb-24">

          {/* Action Bar */}
          <div className="flex flex-wrap items-center gap-2 mb-6 bg-white/70 p-3 rounded-2xl border border-white shadow-sm">
            <button
              onClick={() => setIsHandVisible(false)}
              className="px-3 py-2 rounded-xl bg-slate-800 text-white text-sm font-bold flex items-center gap-2 hover:bg-slate-700"
            >
              <EyeOff className="w-4 h-4" /> ซ่อนไพ่
            </button>

            <div className="flex-1" />

            <button
              onClick={handleRollDice}
              disabled={!canRoll}
              className="px-4 py-2.5 rounded-xl bg-amber-400 text-amber-900 font-black text-sm shadow-md flex items-center gap-2 disabled:opacity-40 transition-transform active:scale-95"
            >
              🎲 ทอยเต๋า
            </button>

            <button
              onClick={handleDrawCard}
              disabled={!canDraw}
              className={`px-4 py-2.5 rounded-xl text-white font-black text-sm shadow-md flex items-center gap-2 disabled:opacity-40 transition-transform active:scale-95 ${viewPlayer.color}`}
            >
              <Hand className="w-5 h-5" /> จั่วไพ่ ({isMyTurn ? turn.draws : 0}/{MAX_DRAWS_PER_TURN})
            </button>

            <button
              onClick={handleEndTurn}
              disabled={!isMyTurn}
              className="px-4 py-2.5 rounded-xl bg-emerald-600 text-white font-black text-sm shadow-md flex items-center gap-2 disabled:opacity-40 transition-transform active:scale-95"
            >
              <SkipForward className="w-4 h-4" /> จบเทิร์น
            </button>
          </div>

          {!isMyTurn && (
            <div className="mb-4 text-xs font-bold text-slate-500 bg-white/60 rounded-xl px-3 py-2 border border-white">
              ตอนนี้ไม่ใช่เทิร์นของผู้เล่นนี้ — ยังใช้ไพ่ตอบโต้ (โล่ / สะท้อนกลับ / หยุดเดี๋ยวนี้) ได้ตามกติกา
            </div>
          )}

          {/* Cards Grid */}
          {sortedHand.length === 0 ? (
            <div className="text-center py-20 opacity-60">
              <div className="text-6xl mb-4">🫧</div>
              <p className="font-bold text-slate-500">ยังไม่มีไพ่บนมือ กดจั่วไพ่เลย!</p>
            </div>
          ) : (
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-x-4 gap-y-6">
              {sortedHand.map(card => (
                <div key={card.uid} className="flex flex-col">
                  <button
                    onClick={() => setPreview(card)}
                    className="relative transition-transform duration-200 hover:-translate-y-1.5 active:scale-95"
                    title="แตะเพื่อดูรายละเอียด"
                  >
                    <CardArt id={card.id} className="w-full h-auto drop-shadow-lg" />
                    <span className={`absolute top-1 right-1 text-[9px] font-black text-white px-1.5 py-0.5 rounded-full shadow ${card.tagColor}`}>
                      {card.tag}
                    </span>
                  </button>
                  <div className="text-[10px] text-slate-500 font-bold text-center leading-tight mt-2 h-7 flex items-center justify-center">
                    {card.desc}
                  </div>
                  <div className="flex gap-1.5 mt-1">
                    <button
                      onClick={() => handlePlayCard(card)}
                      className="flex-1 py-2 rounded-xl bg-emerald-500 text-white text-xs font-black hover:bg-emerald-600 flex items-center justify-center gap-1 transition-colors"
                    >
                      <Play className="w-3.5 h-3.5" /> ใช้ไพ่
                    </button>
                    <button
                      onClick={() => handleDiscardCard(card)}
                      className="px-3 py-2 rounded-xl bg-white text-rose-500 border border-rose-200 text-xs font-black hover:bg-rose-50 flex items-center justify-center gap-1 transition-colors"
                      title="ทิ้งไพ่"
                    >
                      <Trash2 className="w-3.5 h-3.5" /> ทิ้ง
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </main>

      {/* REVEAL MODAL (เปิดไพ่ให้ทุกคนเห็น / ขโมยไพ่) */}
      {reveal && (
        <Overlay z="z-50">
          <div className="bg-white w-full max-w-sm rounded-3xl p-5 shadow-2xl border-4 border-sky-300 text-center max-h-[92vh] overflow-y-auto">
            <div className="text-xs font-black text-sky-500 mb-1">
              {reveal.mode === 'drawn' ? 'จั่วได้ไพ่ที่ต้องเปิดทันที!' : 'เปิดไพ่ให้ทุกคนดู'}
            </div>
            <div className="font-black text-slate-800 mb-3">
              {reveal.playerName} {reveal.mode === 'drawn' ? 'จั่วได้' : 'ใช้ไพ่'} “{reveal.card.name}”
            </div>
            <CardArt id={reveal.card.id} className="w-44 mx-auto animate-pop drop-shadow-xl" />
            <div className="mt-4">
              <TipList tips={reveal.card.tips} />
            </div>

            {reveal.mode === 'steal' ? (
              <div className="mt-5 space-y-2">
                <div className="text-xs font-black text-pink-600">เลือกผู้เล่นที่จะสุ่มขโมยไพ่ 1 ใบ</div>
                {players.filter(p => p.id !== reveal.playerId).map(opp => (
                  <button
                    key={opp.id}
                    onClick={() => executeSteal(opp.id)}
                    className={`w-full p-3 rounded-xl flex items-center justify-between border-2 transition-all ${opp.border} hover:bg-slate-50`}
                  >
                    <span className={`font-black ${opp.text}`}>{opp.name}</span>
                    <span className="text-xs font-bold bg-slate-100 px-3 py-1 rounded-full text-slate-600">
                      มีไพ่ {opp.hand.length} ใบ
                    </span>
                  </button>
                ))}
                <button
                  onClick={cancelSteal}
                  className="w-full py-2.5 rounded-xl bg-indigo-100 text-indigo-700 text-sm font-bold hover:bg-indigo-200"
                >
                  ✋ ถูก “หยุดเดี๋ยวนี้” — ยกเลิกการขโมย
                </button>
              </div>
            ) : (
              <button
                onClick={() => setReveal(null)}
                className="mt-5 w-full py-3 rounded-xl bg-sky-500 text-white font-black hover:bg-sky-600 flex items-center justify-center gap-2"
              >
                รับทราบ
              </button>
            )}
          </div>
        </Overlay>
      )}

      {/* CARD PREVIEW MODAL */}
      {preview && (
        <Overlay z="z-40" onClose={() => setPreview(null)}>
          <div className="bg-white w-full max-w-sm rounded-3xl p-5 shadow-2xl text-center max-h-[92vh] overflow-y-auto relative">
            <button
              onClick={() => setPreview(null)}
              className="absolute top-3 right-3 p-1.5 rounded-full bg-slate-100 hover:bg-slate-200"
            >
              <X className="w-4 h-4" />
            </button>
            <span className={`inline-block text-[10px] font-black text-white px-2 py-0.5 rounded-full mb-2 ${preview.tagColor}`}>
              {preview.tag}
            </span>
            <CardArt id={preview.id} className="w-48 mx-auto drop-shadow-xl" />
            <div className="font-black text-lg text-slate-800 mt-3">{preview.name}</div>
            <div className="text-sm text-slate-500 font-bold mb-3">{preview.desc} • ในสำรับมี {preview.count} ใบ</div>
            <TipList tips={preview.tips} />
          </div>
        </Overlay>
      )}

      {/* WIN PICKER (ครอบครอง 4 เกาะ) */}
      {showWinPicker && (
        <Overlay z="z-50" onClose={() => setShowWinPicker(false)}>
          <div className="bg-white w-full max-w-sm rounded-3xl p-6 shadow-2xl border-4 border-amber-300 text-center">
            <div className="text-5xl mb-2">🏆</div>
            <h3 className="text-xl font-black text-slate-800 mb-1">ใครครอบครองเกาะครบ 4 จาก 5 เกาะ?</h3>
            <p className="text-xs text-slate-500 mb-4">ผู้ชนะทันที ไม่ต้องรอจบเทิร์นหรือสนใจไพ่จบเกม</p>
            <div className="space-y-2">
              {players.map(p => (
                <button
                  key={p.id}
                  onClick={() => declareIslandWin(p)}
                  className={`w-full p-3 rounded-xl border-2 font-black transition-all hover:bg-slate-50 ${p.border} ${p.text}`}
                >
                  {p.name}
                </button>
              ))}
            </div>
            <button
              onClick={() => setShowWinPicker(false)}
              className="mt-4 w-full py-2.5 rounded-xl bg-slate-200 text-slate-700 font-bold hover:bg-slate-300"
            >
              ยกเลิก
            </button>
          </div>
        </Overlay>
      )}

      {/* RULES MODAL */}
      {showRules && (
        <Overlay z="z-40" onClose={() => setShowRules(false)}>
          <div className="bg-white w-full max-w-lg rounded-3xl p-5 shadow-2xl max-h-[92vh] overflow-y-auto relative">
            <button
              onClick={() => setShowRules(false)}
              className="absolute top-3 right-3 p-1.5 rounded-full bg-slate-100 hover:bg-slate-200"
            >
              <X className="w-4 h-4" />
            </button>
            <h3 className="text-xl font-black text-sky-800 mb-1 flex items-center gap-2">
              <BookOpen className="w-5 h-5" /> สรุปไพ่ทั้ง 72 ใบ
            </h3>
            <p className="text-xs text-slate-500 mb-4">
              เทิร์นละ 1 ทางเลือก: ทอยเต๋าแล้วเดิน หรือ จั่วไพ่ 1–2 ใบ • ถือไพ่ได้สูงสุด {MAX_HAND} ใบ
            </p>

            <div className="space-y-3">
              {CARD_ORDER.map(id => {
                const c = CARD_TYPES[id];
                return (
                  <div key={id} className="flex gap-3 items-start bg-slate-50 rounded-2xl p-3 border border-slate-100">
                    <CardArt id={id} className="w-16 shrink-0 drop-shadow-md" />
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 flex-wrap mb-1">
                        <span className="font-black text-slate-800">{c.name}</span>
                        <span className={`text-[9px] font-black text-white px-1.5 py-0.5 rounded-full ${c.tagColor}`}>{c.tag}</span>
                        <span className="text-[10px] font-bold text-slate-400">{c.count} ใบ</span>
                      </div>
                      <TipList tips={c.tips} />
                    </div>
                  </div>
                );
              })}
            </div>

            <h4 className="font-black text-slate-700 mt-5 mb-2">คะแนนบนกระดาน (ใช้ตัดสินเมื่อไม่มีใครครบ 4 เกาะ)</h4>
            <div className="grid grid-cols-2 gap-1.5 text-sm">
              {SCORE_TABLE.map(([name, pts]) => (
                <div key={name} className="flex justify-between bg-sky-50 rounded-lg px-3 py-1.5">
                  <span className="text-slate-600">{name}</span>
                  <span className="font-black text-sky-700">{pts}</span>
                </div>
              ))}
            </div>
            <p className="text-xs text-slate-500 mt-3 leading-relaxed">
              ตัดสิน: 1) ครอบครองเกาะมากที่สุด 2) เท่ากันดูคะแนนรวมบนกระดาน 3) ยังเท่ากัน = เสมอ
              (ตัวเล่นที่อยู่ในฐานไม่นับคะแนน)
            </p>

            <button
              onClick={() => (confirmRestart ? backToSetup() : setConfirmRestart(true))}
              className={`mt-5 w-full py-3 rounded-xl font-black flex items-center justify-center gap-2 ${
                confirmRestart ? 'bg-rose-500 text-white hover:bg-rose-600' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
              }`}
            >
              <RefreshCw className="w-4 h-4" />
              {confirmRestart ? 'กดอีกครั้งเพื่อยืนยัน — เริ่มเกมใหม่' : 'เริ่มเกมใหม่'}
            </button>
          </div>
        </Overlay>
      )}

      {/* GAME OVER */}
      {gameOver && (
        <Overlay z="z-[60]">
          <div className="bg-white w-full max-w-sm rounded-3xl p-6 shadow-2xl border-4 border-amber-300 text-center animate-pop">
            <div className="text-6xl mb-2">🏁</div>
            <h3 className="text-2xl font-black text-slate-800 mb-2">เกมจบแล้ว!</h3>
            <div className="font-black text-sky-700 mb-2">{gameOver.title}</div>
            <p className="text-sm text-slate-500 mb-3 leading-relaxed">{gameOver.detail}</p>
            <p className="text-xs text-slate-400 mb-5 leading-relaxed">
              ถ้าไม่มีใครครบ 4 เกาะ: เกาะมากสุดชนะ → เท่ากันดูคะแนนรวมบนกระดาน → เท่ากันอีก = เสมอ
            </p>
            <button
              onClick={backToSetup}
              className="w-full py-3 rounded-xl bg-sky-500 text-white font-black hover:bg-sky-600"
            >
              เริ่มเกมใหม่
            </button>
            <button
              onClick={() => setGameOver(null)}
              className="mt-2 w-full py-2.5 rounded-xl bg-slate-100 text-slate-600 font-bold hover:bg-slate-200"
            >
              ปิดหน้าต่างนี้ (ดูบันทึกต่อ)
            </button>
          </div>
        </Overlay>
      )}

      {/* TOAST NOTIFICATION */}
      {toast && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 z-[70] bg-slate-800 text-white px-5 py-3 rounded-full shadow-2xl text-sm font-bold flex items-center gap-2 animate-pop max-w-[92vw]">
          <AlertCircle className="w-4 h-4 text-amber-400 shrink-0" />
          <span>{toast}</span>
        </div>
      )}

    </div>
  );
}

